    contractsExportRetrieve(id: string, format?: ContractsExportRetrieveFormatEnum, outputFormat?: ContractsExportRetrieveOutputFormatEnum, version?: ContractsExportRetrieveVersionEnum, options?: RawAxiosRequestConfig): AxiosPromise<void>;

